fn is_greater(n: i32, a: &Vec<i32>) -> bool {
    // Check each element in the array.
    // If any element is greater than or equal to n, return false.
    for &elem in a.iter() {
        if elem >= n {
            return false;
        }
    }
    // If we never found an element >= n, then n is strictly greater than all elements.
    true
}

// Alternatively, using the `all` iterator adaptor:
fn is_greater_all(n: i32, a: &Vec<i32>) -> bool {
    a.iter().all(|&elem| n > elem)
}

